// Simplified Raft node state machine (illustrative, not production)
const FOLLOWER = 'follower';
const CANDIDATE = 'candidate';
const LEADER = 'leader';

class RaftNode {
  constructor(id, peers) {
    this.id = id;
    this.peers = peers;          // array of peer node handles
    this.state = FOLLOWER;
    this.currentTerm = 0;
    this.votedFor = null;
    this.log = [];               // [{term, command}, ...]
    this.commitIndex = -1;
    this.electionTimeout = this.randomElectionTimeout();
  }

  randomElectionTimeout() {
    // Randomized: 150-300ms prevents split votes
    return 150 + Math.random() * 150;
  }

  // Called when election timeout fires with no heartbeat received
  startElection() {
    this.state = CANDIDATE;
    this.currentTerm += 1;
    this.votedFor = this.id; // vote for self
    let votes = 1;
    const majority = Math.floor(this.peers.length / 2) + 1;
    const lastLog = this.log[this.log.length - 1] || { term: 0, index: -1 };

    const votePromises = this.peers.map(peer =>
      peer.requestVote({
        term: this.currentTerm,
        candidateId: this.id,
        lastLogIndex: this.log.length - 1,
        lastLogTerm: lastLog.term
      })
    );

    Promise.allSettled(votePromises).then(results => {
      for (const result of results) {
        if (result.status === 'fulfilled' && result.value.voteGranted) {
          votes++;
        }
      }
      if (votes >= majority && this.state === CANDIDATE) {
        this.becomeLeader();
      }
    });
  }

  becomeLeader() {
    this.state = LEADER;
    console.log(`Node ${this.id} became leader for term ${this.currentTerm}`);
    // Begin sending heartbeat AppendEntries to maintain authority
    this.heartbeatInterval = setInterval(() => this.sendHeartbeats(), 50);
  }

  sendHeartbeats() {
    this.peers.forEach(peer => peer.appendEntries({
      term: this.currentTerm,
      leaderId: this.id,
      entries: [],              // empty = heartbeat
      leaderCommit: this.commitIndex
    }));
  }
}

// Consensus algorithm comparison

// RAFT
// - Designed for understandability
// - Strong leader: all reads/writes go through leader
// - Log replication: leader appends, followers replicate
// - Leader election: randomized timeouts prevent split votes
// - Used by: etcd, CockroachDB, TiKV, Consul, RethinkDB

// PAXOS
// - Designed for correctness proof
// - No persistent leader concept (Multi-Paxos adds one)
// - Two phases: Prepare (ballot) + Accept (value)
// - More flexible but harder to implement correctly
// - Used by: Google Chubby, Google Spanner (modified)

// QUORUM MATH
// N=3: quorum=2, tolerates 1 failure
// N=5: quorum=3, tolerates 2 failures
// N=7: quorum=4, tolerates 3 failures
// Rule: quorum = Math.floor(N / 2) + 1

// EVEN vs ODD nodes:
const quorum = n => Math.floor(n / 2) + 1;
console.log(quorum(3)); // 2 — tolerates 1 failure
console.log(quorum(4)); // 3 — tolerates 1 failure (same!)
console.log(quorum(5)); // 3 — tolerates 2 failures
// Prefer odd cluster sizes — 4 nodes is no better than 3 for fault tolerance

// KEY SAFETY PROPERTY (both Raft and Paxos):
// At most one leader per term — two leaders cannot both commit different values
// for the same log index. Quorum intersection guarantees this: any two majorities
// share at least one node that would reject the second leader's ballot.
